-- Catalogo curado de supermercados espanoles para DanTal.
-- Fuente: Open Food Facts / Search-a-licious. Licencia ODbL 1.0 / DbCL 1.0.
-- Datos colaborativos y orientativos: comprueba siempre la etiqueta.
-- Se importa una muestra representativa; el catalogo completo esta en
-- supabase/catalogo-supermercados.json y se carga en la app sin red.

on conflict (tipo, id) do update set datos = excluded.datos, activo = true, actualizado = now();

update public.catalogos set activo = true where tipo = 'alimento' and id like 'off-%';
